package com.campusnova.config; import com.campusnova.model.*; import com.campusnova.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.util.*;
@Configuration public class DemoDataConfig { @Bean CommandLineRunner demo(CategoryRepository c,FaqRepository f,AnnouncementRepository a){return x->{if(c.count()>0)return; Map<String,Category> m=new HashMap<String,Category>();String[] names={"Admissions","Courses","Fees","Examinations","Timetable","Placements","Library","Facilities","Contact","Campus"};for(String n:names)m.put(n,c.save(new Category(n,"•"))); seed(f,m,"Admissions","What documents are required for admission?","For this demo, keep your mark sheets, transfer certificate, ID proof, photographs and the applicable admission receipt ready. Confirm the current official list with the college office.","admission documents certificate apply");seed(f,m,"Courses","What courses are available?","CampusNova demo data lists undergraduate engineering programmes and programme-specific electives. Please consult the official prospectus for the current approved intake and course list.","courses programmes branches degree");seed(f,m,"Fees","How much is the fee?","Fee amounts vary by programme, admission category and semester. Contact the accounts office for the verified current fee structure; this prototype intentionally does not present demo figures as official.","fee fees payment tuition accounts");seed(f,m,"Examinations","When are the exams?","Examination dates are announced through the official academic calendar and notice board. Check the latest university notification for confirmed dates.","exam exams examination schedule date");seed(f,m,"Timetable","What is today's class schedule?","Today's schedule is maintained by your department. Check your class notice group or department timetable for the latest room and period changes.","today class schedule timetable periods");seed(f,m,"Placements","Tell me about placements.","The placement cell supports career readiness, training and recruitment coordination. Watch official placement notices for eligible drives, dates and registration instructions.","placement placements career recruitment job");seed(f,m,"Library","What are the library timings?","Demo library hours: 9:00 AM to 7:00 PM on working days. Please verify holiday and examination-period hours with the library desk.","library timings open close hours");seed(f,m,"Library","Where is the library?","The library location is displayed on the campus directory. For a current route, please ask the reception or library desk.","library location where");seed(f,m,"Facilities","Where is the computer lab?","Computer lab allocation is department-specific. Check the departmental notice board or ask your faculty coordinator for the currently assigned lab.","computer lab location facilities");seed(f,m,"Contact","How can I contact the administration?","Contact the administration through the college office during working hours or use the official contact information published by the institution.","contact administration office phone email");a.save(new Announcement("Welcome to CampusNova","NOVA is running with clearly marked demonstration knowledge. Administrators can update answers without changing source code."));};} private void seed(FaqRepository f,Map<String,Category>m,String c,String q,String a,String k){f.save(new Faq(m.get(c),q,a,k));} }
